import type { Translations } from "../i18n";
import {
  CATEGORY_LABELS,
  HORIZONS,
  INVESTMENT_OPTIONS,
  RISK_LEVELS,
  SECTOR_LABELS,
  SOURCES,
} from "../ireland-investment.ts";

/* The investment planner's data, in every language: the 32 options keyed by
   id, the labels, and the source topics keyed by URL. English is read
   straight from lib/ireland-investment.ts so it cannot drift; the figures in
   the other languages were copied from it on 13 October 2026 (Bangla and
   Hindi on 26 October 2026), so when
   DATA_AS_OF moves, these notes move with it. Provider, product and document
   names stay as their owners write them. */

type OptionText = {
  name: string;
  taxTreatment: string;
  liquidity: string;
  cap: string;
  note: string;
  link: string;
};

const en = {
  options: Object.fromEntries(
    INVESTMENT_OPTIONS.map((o) => [
      o.id,
      { name: o.name, taxTreatment: o.taxTreatment, liquidity: o.liquidity, cap: o.cap, note: o.note, link: o.link.label },
    ]),
  ) as Record<string, OptionText>,
  sectors: { ...SECTOR_LABELS } as Record<string, string>,
  categories: { ...CATEGORY_LABELS } as Record<string, string>,
  horizons: Object.fromEntries(HORIZONS.map((h) => [h.value, { label: h.label, blurb: h.blurb }])) as Record<string, { label: string; blurb: string }>,
  risks: Object.fromEntries(RISK_LEVELS.map((r) => [r.value, { label: r.label, blurb: r.blurb }])) as Record<string, { label: string; blurb: string }>,
  topics: Object.fromEntries(SOURCES.map((s) => [s.url, s.topic])) as Record<string, string>,
};

export type InvestmentData = typeof en;

const URL = Object.fromEntries(SOURCES.map((s, i) => [i, s.url])) as Record<number, string>;
/* Topics in SOURCES order. */
const topics = (list: string[]) => Object.fromEntries(list.map((t, i) => [URL[i], t]));

